// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 dep) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        try c.Collect(dep) {} catch { return; }
        assertTrue(c.balances(address(this)) == 0);
    }

    function testFuzz_run(uint256 dep) public {
        _run(dep);
    }

    receive() external payable {}
}
